package mx.com.mesaregia.inventario.application.service.impl;
import mx.com.mesaregia.inventario.application.service.AjusteInventarioService; import mx.com.mesaregia.inventario.api.request.AjusteInventarioRequest; import mx.com.mesaregia.inventario.api.response.MovimientoResponse; import mx.com.mesaregia.inventario.domain.enums.*; import mx.com.mesaregia.inventario.exception.*; import mx.com.mesaregia.inventario.mapper.InventarioMapper; import mx.com.mesaregia.inventario.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service
public class AjusteInventarioServiceImpl implements AjusteInventarioService {
 private final InventorySupport support; private final ExistenciaRepository er; private final MovimientoInventarioRepository mr; private final CorteFisicoRepository cr; public AjusteInventarioServiceImpl(InventorySupport s,ExistenciaRepository e,MovimientoInventarioRepository m,CorteFisicoRepository c){support=s;er=e;mr=m;cr=c;}
 @Override @Transactional public MovimientoResponse registrar(String key,AjusteInventarioRequest q){ String op=support.operationKey(key,"AJUSTE|"+q.idAlmacen()+"|"+q.idProducto()); var old=mr.findByClaveOperacion(op); if(old.isPresent())return InventarioMapper.movimiento(old.get()); var e=support.existenciaForUpdate(q.idAlmacen(),q.idProducto()); int antes=e.getExistenciaFisica(), despues=q.cantidadFisicaCorregida(); if(antes==despues) throw new BusinessRuleException("El ajuste debe modificar la existencia"); var corte=q.idCorteFisico()==null?null:cr.findById(q.idCorteFisico()).orElseThrow(()->new ResourceNotFoundException("Corte físico no encontrado")); e.setExistenciaFisica(despues);er.saveAndFlush(e);int cantidad=Math.abs(despues-antes); return InventarioMapper.movimiento(support.movimiento(e,TipoMovimiento.AJUSTE,OrigenOperacion.AJUSTE_AUTORIZADO,cantidad,antes,despues,null,corte,q.motivo(),q.comentario(),q.idUsuarioExterno(),op)); }
}
